INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8bb0-79e6-ade9-c46eddf891d7'::uuid, '019f9df7-a2a2-7888-aef2-fd58477eb864'::uuid, 'A cumulative frequency graph for 160 students shows the lower quartile at 56 marks and the upper quartile at 72 marks. Find the interquartile range.', '16', 'Interquartile range = upper quartile - lower quartile = 72 - 56 = 16.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.464Z'::timestamptz, '2026-08-15T07:36:12.464Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8bb6-77a0-8cd3-3690d5b4530c'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Write as a single fraction in its simplest form: 3/(x + 2) + 1/(x - 2).', '(4x - 4)/(x^2 - 4)', 'The common denominator is (x + 2)(x - 2) = x^2 - 4. The numerator becomes 3(x - 2) + (x + 2) = 4x - 4. So the single fraction is (4x - 4)/(x^2 - 4).', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.470Z'::timestamptz, '2026-08-15T07:36:12.470Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8bc7-7e97-891d-72fad8fdb80e'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Expand and simplify (2x - 5)(x + 4).', '2x^2 + 3x - 20', 'Multiply each term: 2x(x + 4) - 5(x + 4) = 2x^2 + 8x - 5x - 20 = 2x^2 + 3x - 20.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.487Z'::timestamptz, '2026-08-15T07:36:12.487Z'::timestamptz) ON CONFLICT (id) DO NOTHING;